    if (P.snap) Se(o, at(sr, r, 0.02, 0.003, { hp: 1200, lp: 8000 }), 2e-4, P.snap, sr);
    const T = P.thump; if (T) Se(o, ei(sr, T.len, T.f0 * n, T.f1 * n, T.fall, T.amp, T.att || 0.003), T.t || 0, T.g, sr);
