    const L = P.blat; if (L) Se(o, at(sr, r, L.len, L.dec, { bp: L.bp * n, q: L.q, att: 0.001 }), 0, L.g, sr);
    const A = P.air; if (A) Se(o, at(sr, r, A.len, A.dec, { hp: A.hp }), 0.001, A.g, sr);
